"""Generated by G2C: one request through the declared steps, with the model bound from E2A's
"simulated" profile (whatever profile the deployment uses)."""
from e2a import bindings_from_profile
from e2a_simulated_llm import system_contains

from genai_assistant_service.tools.catalog import tools
from genai_assistant_service.workflow.investigation_workflow import InvestigationWorkflow


def test_one_request_runs_the_declared_steps():
    bindings = bindings_from_profile("simulated", verify=True)
    llm = bindings.llm_service
    llm.add_rule('IntentAgent', system_contains("You are IntentAgent."), '{"intent": "INVESTIGATE"}')
    llm.add_rule('InvestigatorAgent', system_contains("You are InvestigatorAgent."), '{"answer": "x", "citations": [], "verified": [], "inferred": []}')
    llm.add_rule('ProposalAgent', system_contains("You are ProposalAgent."), '{"action": "WRITE_OFF", "settlement_id": "x", "amount": "x", "currency": "x", "reason": "x"}')
    state = InvestigationWorkflow().execute({"tenant_id": "test-tenant", "query": "test"},
                                     bindings.config(tools=tools()), idempotency_key="test-1")
    assert state["steps"][0]["step"] == 'route'
    assert all(s["status"] in ("DONE", "SKIPPED", "FALLBACK") for s in state["steps"]), state["steps"]
